1	/**
2	 * @file main.c
3	 * @brief lvgl_sim 入口：参数解析 → LVGL 初始化 → 场景 → 主循环。
4	 *
5	 *   ./lvgl_sim                       # 默认 demo 场景，240x320 @2x 窗口
6	 *   ./lvgl_sim --scene vmap          # vmap 底图 mock
7	 *   ./lvgl_sim --scale 3             # 放大到 3 倍
8	 *   ./lvgl_sim --headless --frames 40 --shot out.png
9	 */
10	
11	#include <getopt.h>
12	#include <math.h>
13	#include <stdio.h>
14	#include <stdlib.h>
15	#include <string.h>
16	#include <unistd.h>
17	
18	#include "sim.h"
19	
20	uint32_t sim_tick_ms(void);
21	
22	static uint32_t s_vtick;
23	
24	static uint32_t vtick_get(void)
25	{
26	    return s_vtick;
27	}
