29	static const char *const kUsageLines[] = {
30	    "用法: lvgl_sim [选项]",
31	    "  -s, --scene NAME    场景（demo | vmap | vmap-mock | ui），默认 demo",
32	    "  -S, --size WxH      设备分辨率，默认 240x320（设备原生竖屏）",
33	    "  -k, --scale N       窗口放大倍数，默认 2",
34	    "  -H, --headless      不建窗口，跑固定帧数",
35	    "  -f, --frames N      headless 帧数，默认 30",
36	    "  -o, --shot PATH     headless 截图输出 PNG",
37	    "  -t, --title TEXT    窗口标题",
38	    "      --ui-tour DIR   巡页模式（仅 --scene ui）：逐页/逐主题截图到 DIR",
39	    "      --tour-frames N 巡页每页等待帧数，默认 90",
40	    "",
41	    "  --scene vmap（真 vmap 组件）:",
42	    "      --vmap-viewport WxH     可视窗口尺寸（运行时生效），默认 = 屏幕",
43	    "      --vmap-center LON,LAT   地图中心（直接定位），默认板端开机中心",
44	    "      --vmap-scale S          连续缩放（z14 瓦片不换层），默认 1.69",
45	    "      --vmap-zoom Z           瓦片层级，默认 14",
46	    "      --vmap-icon dev|alt|none 中心图标：板端箭头 / 准星 / 不画",
47	    "      --vmap-pan DX,DY        首帧后脚本化平移（像素，验证拖动）",
48	    "      --vmap-resize WxH       首帧后**运行时**改 viewport 尺寸（验证 set_viewport）",
49	    "      --vmap-hud 0|1          HUD 开关，默认 1",
50	    "      --vmap-heading 0|1      航向朝上（R 缓冲旋转显示），默认 0",
51	    "      --vmap-course DEG       航向角（正北 0，顺时针），配合 --vmap-heading",
52	    "      --vmap-zoom-at X,Y,F    首帧后锚点缩放（可给两次），验证 zoom_at 锚点不动",
53	    "      --vmap-drag N,DX,DY     首帧后连续 N 次 pan_px(DX,DY)，验证亚像素累积",
54	    "      --vmap-icon-swap SRC    首帧后运行时换图（可给 3 次，dev|alt|none）",
55	    "      --vmap-recenter         拖动之后调 center_on() 回中（验证可回中、不弹回）",
56	    "      --vmap-follow N,M        首帧后喂 N 个 GNSS 点、每点东移 M 米（板端跟车热路径）",
57	    "      （窗口模式下：鼠标拖动 = 平移，滚轮 = 缩放；",
58	    "        按键 1/2/3 = 换图标，c = 轮换中心点，+/- = 缩放，r = 复位，f = 跟随开关）",
59	    "  -l, --list          列出所有场景",
60	    "  -h, --help          本帮助",
61	    NULL,
62	};
63	
64	static void usage(void)
65	{
66	    for (int i = 0; kUsageLines[i]; i++) {
67	        puts(kUsageLines[i]);
68	    }
69	}
