71	int main(int argc, char **argv)
72	{
73	    sim_cfg_t cfg;
74	    memset(&cfg, 0, sizeof(cfg));
75	    cfg.width = 240;
76	    cfg.height = 320;   /* 设备原生竖屏：状态栏 24 + 页面 296 */
77	    cfg.scale = 2;
78	    cfg.frames = 30;
79	    cfg.tour_frames = 90;
80	    cfg.title = "lvgl_sim";
81	    cfg.vmap_lon = NAN;   /* = 用组件默认中心 */
82	    cfg.vmap_lat = NAN;
83	    cfg.vmap_hud = true;
84	
85	    const char *scene_name = "demo";
86	    bool list_only = false;
87	
88	    enum {
89	        OPT_UI_TOUR = 256,
90	        OPT_TOUR_FRAMES,
91	        OPT_VMAP_VIEWPORT,
92	        OPT_VMAP_CENTER,
93	        OPT_VMAP_SCALE,
94	        OPT_VMAP_ZOOM,
95	        OPT_VMAP_ICON,
96	        OPT_VMAP_PAN,
97	        OPT_VMAP_RESIZE,
98	        OPT_VMAP_HUD,
99	        OPT_VMAP_HEADING,
100	        OPT_VMAP_COURSE,
101	        OPT_VMAP_ZOOM_AT,
102	        OPT_VMAP_DRAG,
103	        OPT_VMAP_ICON_SWAP,
104	        OPT_VMAP_RECENTER,
105	        OPT_VMAP_FOLLOW,
106	    };
107	
108	    static const struct option long_opts[] = {
109	        { "scene",    required_argument, 0, 's' },
110	        { "size",     required_argument, 0, 'S' },
111	        { "scale",    required_argument, 0, 'k' },
112	        { "headless", no_argument,       0, 'H' },
113	        { "frames",   required_argument, 0, 'f' },
114	        { "shot",     required_argument, 0, 'o' },
115	        { "title",    required_argument, 0, 't' },
116	        { "ui-tour",  required_argument, 0, OPT_UI_TOUR },
117	        { "tour-frames", required_argument, 0, OPT_TOUR_FRAMES },
118	        { "vmap-viewport", required_argument, 0, OPT_VMAP_VIEWPORT },
119	        { "vmap-center", required_argument, 0, OPT_VMAP_CENTER },
120	        { "vmap-scale", required_argument, 0, OPT_VMAP_SCALE },
121	        { "vmap-zoom", required_argument, 0, OPT_VMAP_ZOOM },
122	        { "vmap-icon", required_argument, 0, OPT_VMAP_ICON },
123	        { "vmap-pan", required_argument, 0, OPT_VMAP_PAN },
124	        { "vmap-resize", required_argument, 0, OPT_VMAP_RESIZE },
125	        { "vmap-hud", required_argument, 0, OPT_VMAP_HUD },
126	        { "vmap-heading", required_argument, 0, OPT_VMAP_HEADING },
127	        { "vmap-course", required_argument, 0, OPT_VMAP_COURSE },
128	        { "vmap-zoom-at", required_argument, 0, OPT_VMAP_ZOOM_AT },
129	        { "vmap-drag", required_argument, 0, OPT_VMAP_DRAG },
130	        { "vmap-icon-swap", required_argument, 0, OPT_VMAP_ICON_SWAP },
131	        { "vmap-recenter", no_argument, 0, OPT_VMAP_RECENTER },
132	        { "vmap-follow", required_argument, 0, OPT_VMAP_FOLLOW },
133	        { "list",     no_argument,       0, 'l' },
134	        { "help",     no_argument,       0, 'h' },
135	        { NULL, 0, NULL, 0 },
136	    };
137	
138	    int c;
139	    while ((c = getopt_long(argc, argv, "s:S:k:Hf:o:t:lh", long_opts, NULL)) != -1) {
140	        switch (c) {
141	            case 's': scene_name = optarg; break;
142	            case 'S':
143	                if (sscanf(optarg, "%dx%d", &cfg.width, &cfg.height) != 2) {
144	                    fprintf(stderr, "bad --size\n");
145	                    return 2;
146	                }
147	                break;
148	            case 'k': cfg.scale = atoi(optarg); break;
149	            case 'H': cfg.headless = true; break;
150	            case 'f': cfg.frames = atoi(optarg); break;
151	            case 'o': cfg.shot = optarg; break;
152	            case 't': cfg.title = optarg; break;
153	            case OPT_UI_TOUR: cfg.ui_tour = optarg; break;
154	            case OPT_TOUR_FRAMES: cfg.tour_frames = atoi(optarg); break;
155	            case OPT_VMAP_VIEWPORT:
156	                if (sscanf(optarg, "%dx%d", &cfg.vmap_w, &cfg.vmap_h) != 2) {
157	                    fprintf(stderr, "bad --vmap-viewport (want WxH)\n");
158	                    return 2;
159	                }
160	                break;
161	            case OPT_VMAP_CENTER:
162	                if (sscanf(optarg, "%lf,%lf", &cfg.vmap_lon, &cfg.vmap_lat) != 2) {
163	                    fprintf(stderr, "bad --vmap-center (want LON,LAT)\n");
164	                    return 2;
165	                }
166	                break;
167	            case OPT_VMAP_SCALE: cfg.vmap_scale = atof(optarg); break;
168	            case OPT_VMAP_ZOOM: cfg.vmap_zoom = atoi(optarg); break;
169	            case OPT_VMAP_ICON:
170	                if (strcmp(optarg, "dev") == 0) {
171	                    cfg.vmap_icon = SIM_VMAP_ICON_DEV;
172	                } else if (strcmp(optarg, "alt") == 0) {
173	                    cfg.vmap_icon = SIM_VMAP_ICON_ALT;
174	                } else if (strcmp(optarg, "none") == 0) {
175	                    cfg.vmap_icon = SIM_VMAP_ICON_NONE;
176	                } else {
177	                    fprintf(stderr, "bad --vmap-icon (dev|alt|none)\n");
178	                    return 2;
179	                }
180	                break;
181	            case OPT_VMAP_PAN:
182	                if (sscanf(optarg, "%d,%d", &cfg.vmap_pan_x, &cfg.vmap_pan_y) != 2) {
183	                    fprintf(stderr, "bad --vmap-pan (want DX,DY)\n");
184	                    return 2;
185	                }
186	                cfg.vmap_pan_set = true;
187	                break;
188	            case OPT_VMAP_RESIZE:
189	                if (sscanf(optarg, "%dx%d", &cfg.vmap_rw, &cfg.vmap_rh) != 2) {
190	                    fprintf(stderr, "bad --vmap-resize (want WxH)\n");
191	                    return 2;
192	                }
193	                break;
194	            case OPT_VMAP_HUD: cfg.vmap_hud = atoi(optarg) != 0; break;
195	            case OPT_VMAP_HEADING: cfg.vmap_heading = atoi(optarg) != 0; break;
196	            case OPT_VMAP_COURSE: cfg.vmap_course = atof(optarg); break;
197	            case OPT_VMAP_ZOOM_AT:
198	                if (cfg.vmap_zoom_at_n >= 2) {
199	                    fprintf(stderr, "bad --vmap-zoom-at (max 2)\n");
200	                    return 2;
201	                }
202	                {
203	                    const int i = cfg.vmap_zoom_at_n;
204	
205	                    if (sscanf(optarg, "%d,%d,%lf", &cfg.vmap_za_x[i],
206	                            &cfg.vmap_za_y[i], &cfg.vmap_za_f[i]) != 3 || cfg.vmap_za_f[i] <= 0.0) {
207	                        fprintf(stderr, "bad --vmap-zoom-at (want X,Y,FACTOR)\n");
208	                        return 2;
209	                    }
210	                }
211	                cfg.vmap_zoom_at_n++;
212	                break;
213	            case OPT_VMAP_RECENTER: cfg.vmap_recenter = true; break;
214	            case OPT_VMAP_FOLLOW:
215	                if (sscanf(optarg, "%d,%lf", &cfg.vmap_follow_n, &cfg.vmap_follow_m) != 2
216	                    || cfg.vmap_follow_n <= 0 || !(cfg.vmap_follow_m > 0.0)) {
217	                    fprintf(stderr, "bad --vmap-follow (want N,METERS)\n");
218	                    return 2;
219	                }
220	                break;
221	            case OPT_VMAP_ICON_SWAP: {
222	                int icon;
223	
224	                if (strcmp(optarg, "dev") == 0) {
225	                    icon = SIM_VMAP_ICON_DEV;
226	                } else if (strcmp(optarg, "alt") == 0) {
227	                    icon = SIM_VMAP_ICON_ALT;
228	                } else if (strcmp(optarg, "none") == 0) {
229	                    icon = SIM_VMAP_ICON_NONE;
230	                } else {
231	                    fprintf(stderr, "bad --vmap-icon-swap (dev|alt|none)\n");
232	                    return 2;
233	                }
234	                if (cfg.vmap_swap_n >= 3) {
235	                    fprintf(stderr, "bad --vmap-icon-swap (max 3)\n");
236	                    return 2;
237	                }
238	                cfg.vmap_swap_icon[cfg.vmap_swap_n++] = icon;
239	                break;
240	            }
241	            case OPT_VMAP_DRAG:
242	                if (sscanf(optarg, "%d,%d,%d", &cfg.vmap_drag_n,
243	                        &cfg.vmap_drag_x, &cfg.vmap_drag_y) != 3 || cfg.vmap_drag_n <= 0) {
244	                    fprintf(stderr, "bad --vmap-drag (want N,DX,DY)\n");
245	                    return 2;
246	                }
247	                break;
248	            case 'l': list_only = true; break;
249	            case 'h': usage(); return 0;
250	            default: usage(); return 2;
251	        }
252	    }
253	
254	    if (list_only) {
255	        sim_scene_list();
256	        return 0;
257	    }
258	
259	    const sim_scene_t *scene = sim_scene_find(scene_name);
260	    if (!scene) {
261	        fprintf(stderr, "unknown scene\n");
262	        sim_scene_list();
263	        return 2;
264	    }
265	
266	    /* Helm 的按键提示写进窗口标题：不点终端也知道 ←/→/↑ 干什么。 */
267	    const bool helm_scene = (strcmp(scene->name, "helm") == 0);
268	
269	    if (helm_scene) {
270	        cfg.title = "lvgl_sim · helm — ←=KEY1  →=KEY2  ↑=power";
271	    }
272	
273	    lv_init();
274	    lv_tick_set_cb(cfg.headless ? vtick_get : sim_tick_ms);
275	
276	    if (!sim_display_init(&cfg)) {
277	        return 1;
278	    }
279	    sim_lvgl_bind();
280	
281	    scene->create(lv_screen_active(), &cfg);
282	    printf("lvgl_sim: scene=%s %dx%d scale=%d %s\n", scene->name, cfg.width,
283	           cfg.height, cfg.scale, cfg.headless ? "headless" : "window");
284	    if (helm_scene) {
285	        printf("keys: ←=KEY1  →=KEY2  ↑=power  (短按=轻点，长按=按住 ≥800ms；"
286	               "数字 1/2/3 等价)\n");
287	    }
288	
289	    if (cfg.ui_tour != NULL && cfg.tour_frames <= 0) {
290	        cfg.tour_frames = 90;
291	    }
292	
293	    if (cfg.headless) {
294	        /* 巡页模式下帧数由巡页状态机自己决定，这里只给一个死循环保护。
295	         * 只有 `ui` 场景会真正启用巡页（见 scenes.c）；其它场景带 --ui-tour
296	         * 也完全按原来的 --frames 跑。 */
297	        int frames = cfg.frames;
298	
299	#ifdef SIM_WITH_UI
300	        const bool tour = sim_ui_tour_enabled();
301	
302	        if (tour) {
303	            frames = 6000;
304	        }
305	#endif
306	        for (int i = 0; i < frames; i++) {
307	            s_vtick += 16;
308	            lv_timer_handler();
309	#ifdef SIM_WITH_UI
310	            if (tour && sim_ui_tour_done()) {
311	                break;
312	            }
313	            /* WP-FADE/R1 临时探针跑完即退出（未启用时恒为 false）。 */
314	            if (sim_ui_fade_probe_done()) {
315	                break;
316	            }
317	#endif
318	        }
319	        if (cfg.shot) {
320	            int w = 0;
321	            int h = 0;
322	            const uint16_t *fb = sim_display_shadow(&w, &h);
323	
324	            if (!sim_png_write(cfg.shot, fb, w, h)) {
325	                fprintf(stderr, "failed to write png\n");
326	                sim_display_shutdown();
327	                return 1;
328	            }
329	            printf("shot -> %s (%dx%d)\n", cfg.shot, w, h);
330	        }
331	    } else {
332	        while (sim_display_pump()) {
333	            uint32_t idle = lv_timer_handler();
334	
335	#ifdef SIM_WITH_UI
336	            if (sim_ui_tour_enabled() && sim_ui_tour_done()) {
337	                break;
338	            }
339	#endif
340	            if (idle < 1) {
341	                idle = 1;
342	            }
343	            if (idle > 16) {
344	                idle = 16;
345	            }
346	            usleep(idle * 1000);
347	        }
348	    }
349	
350	    sim_display_shutdown();
351	    return 0;
352	}
