669	static int hr_zone(int bpm)
670	{
671	    if (bpm < 118) return 1;
672	    if (bpm < 132) return 2;
673	    if (bpm < 140) return 3;
674	    if (bpm < 160) return 4;
675	    return 5;
676	}
677	
678	/** 心率指针落点 x（2px 宽：像素 x..x+1）。
679	 *
680	 *  分段线性，每格正好一个分区：五格等宽 30/30/31/30/31 px，格内再按该分区
681	 *  的 bpm 区间线性细分。这样「指针在第 i 格」⇔ `hr_zone(bpm) == i`，
682	 *  不会出现指针在 Z3 而四格显示 Z2 的矛盾。
683	 *
684	 *  t = (段号 + 段内比例) / 5 ∈ [0,1]，x = 64 + round(152·t) − 1。
685	 *  例：148 bpm → Z4(140..160) → t = (3 + 8/20)/5 = 0.68
686	 *      → x = 64 + round(103.36) − 1 = 166（像素 166..167，落在第 4 格 155..184）。
687	 *      120 bpm → Z2(118..132) → t = (1 + 2/14)/5 ≈ 0.2286
688	 *      → x = 64 + round(34.74) − 1 = 98（像素 98..99，落在第 2 格 94..123）。
689	 */
690	static int hr_bar_x(int bpm)
691	{
692	    double t;
693	
694	    if (bpm < HR_MIN_BPM) bpm = HR_MIN_BPM;
695	    if (bpm > HR_MAX_BPM) bpm = HR_MAX_BPM;
696	    if (bpm < 118) {
697	        t = (double)(bpm - HR_MIN_BPM) / (118.0 - HR_MIN_BPM);
698	    } else if (bpm < 132) {
699	        t = 1.0 + (double)(bpm - 118) / (132.0 - 118.0);
700	    } else if (bpm < 140) {
701	        t = 2.0 + (double)(bpm - 132) / (140.0 - 132.0);
702	    } else if (bpm < 160) {
703	        t = 3.0 + (double)(bpm - 140) / (160.0 - 140.0);
704	    } else {
705	        t = 4.0 + (double)(bpm - 160) / (HR_MAX_BPM - 160.0);
706	    }
707	    t /= 5.0;
708	    {
709	        int x = HR_BAR_X0 + (int)lround((double)HR_BAR_W * t) - 1;
710	
711	        if (x < HR_BAR_X0) x = HR_BAR_X0;
712	        if (x > HR_BAR_X0 + HR_BAR_W - BAR_PTR_W) {
713	            x = HR_BAR_X0 + HR_BAR_W - BAR_PTR_W;
714	        }
715	        return x;
716	    }
717	}
