719	/** 最近 60 s 假心率序列的统计：均值四舍五入、峰值取最大值。
720	 *
721	 *  v[i] = clamp(R.hr + s_hr_delta[i], 60, 200)，i = 0..30；
722	 *  mean = (Σv + N/2) / N（整数除法 = 四舍五入）；
723	 *  peak = max(v)。
724	 *  例：R.hr = 148 时 Σv = 31·148 − 466 = 4122，
725	 *  mean = (4122 + 15)/31 = 4137/31 = 133，peak = 148 + 0 = 148。 */
726	static void hr_hist_stats(int *avg, int *peak)
727	{
728	    int sum = 0;
729	    int mx = -1000;
730	
731	    for (int i = 0; i < HR_HIST_N; i++) {
732	        int v = R.hr + s_hr_delta[i];
733	
734	        if (v < HR_MIN_BPM) v = HR_MIN_BPM;
735	        if (v > HR_MAX_BPM) v = HR_MAX_BPM;
736	        sum += v;
737	        if (v > mx) mx = v;
738	    }
739	    *avg = (sum + HR_HIST_N / 2) / HR_HIST_N;
740	    *peak = mx;
741	}
