785	/** 自动暂停：速度 < 2 km/h 连续 10 s 触发；>= 2.5 km/h 自动恢复。 */
786	#define AUTO_PAUSE_ENTER_KMH 2.0
787	#define AUTO_PAUSE_EXIT_KMH  2.5
788	#define AUTO_PAUSE_HOLD_S    10
789	
790	static void ride_step(void)
791	{
792	    R.seed = R.seed * 1103515245u + 12345u;
793	    R.t += 1.0;
794	    {
795	        const double n = (double)((R.seed >> 16) & 0x7FFF) / 32767.0 - 0.5;
796	        double sp = 22.5 + 5.5 * sin(R.t / 8.0) + 1.6 * n;
797	
798	        /* 演示语义：每 60 s 有一个 14 s 的“红灯/推车”段（速度 0），
799	         * 自动暂停在静止 10 s 后触发、放行后自动恢复。 */
800	        if (fmod(R.t, 60.0) >= 46.0) {
801	            sp = 0.0;
802	        }
803	        if (sp > 0.0 && sp < 8.0) sp = 8.0;
804	        if (sp > 45.0) sp = 45.0;
805	        R.target = sp;
806	        if (R.paused) {
807	            R.speed = 0.0;
808	            R.cadence = 0;
809	            R.power = 0;
810	            if (R.hr > 96) R.hr--;
811	            return;
812	        }
813	        R.speed = sp;
814	        R.dist_km += sp / 3600.0;
815	        R.hr = 126 + (int)(sp * 1.05) + (int)(3.0 * n);
816	        R.cadence = sp <= 0.0 ? 0 : 78 + (int)(sp * 0.5) + (int)(4.0 * n);
817	        R.power = sp <= 0.0 ? 0 : (int)(120.0 + sp * 2.6 + 10.0 * n);
818	        R.elevation = 326 + (int)(9.0 * sin(R.t / 21.0));
819	        if (n > 0.28) {
820	            R.ascent += 1;
821	        }
822	        R.cal = (int)(R.dist_km * 32.0);
823	        if (R.speed > R.max) {
824	            R.max = R.speed;
825	        }
826	        R.avg = (R.elapsed_s > 0)
827	                    ? R.dist_km / ((double)R.elapsed_s / 3600.0)
828	                    : R.speed;
829	    }
830	    {
831	        const double s = R.speed;
832	        const int bin = (s < 15.0) ? 0 : (s < 25.0) ? 1 : (s < 35.0) ? 2
833	                      : (s < 45.0) ? 3 : 4;
834	
835	        R.hist[bin]++;
836	    }
837	}
