839	/** 1 Hz 骑行推进（暂停时停表/停里程；自动暂停判定用未门控速度）。 */
840	static void ride_advance_1s(void)
841	{
842	    if (!R.active) {
843	        return;
844	    }
845	    if (!R.paused) {
846	        R.elapsed_s++;      /* 先记这一秒，ride_step() 的均速用同一分母 */
847	    }
848	    ride_step();
849	    if (!R.paused && R.target < AUTO_PAUSE_ENTER_KMH) {
850	        R.still_s++;
851	        if (R.still_s >= AUTO_PAUSE_HOLD_S) {
852	            R.paused = true;
853	            R.auto_paused = true;
854	            R.speed = 0.0;
855	            R.cadence = 0;
856	            R.power = 0;
857	            toast("自动暂停 · 速度低于 2 km/h");
858	        }
859	    } else if (!R.paused) {
860	        R.still_s = 0;
861	    }
862	    if (R.paused && R.auto_paused && R.target >= AUTO_PAUSE_EXIT_KMH) {
863	        R.paused = false;
864	        R.auto_paused = false;
865	        R.still_s = 0;
866	        toast("自动继续");
867	    }
868	}
