1361	    s_rot_oa_cur = s_rot_oa0 * (1000 - (int)p) / 1000;
1362	    s_rot_ob_cur = s_rot_ob0 + (255 - s_rot_ob0) * (int)p / 1000;
1363	    SET_ARC_OPA(UD.fill, s_rot_oa_cur);
1364	    SET_ARC_OPA(UD.trk, s_rot_oa_cur);
1365	    SET_ARC_OPA(UD.fill2, s_rot_ob_cur);
1366	    SET_ARC_OPA(UD.trk2, s_rot_ob_cur);
1367	    if (!s_rot_swapped && p >= 500) {
1368	        s_rot_swapped = true;
1369	        dial_content(s_rot_to_mode);
1370	    }
1371	}
