1401	static void dial_rotate_next(void)
1402	{
1403	    int from_mode;
1404	    int to_mode;
1405	    int a0;
1406	    int target;
1407	    int duration = 160;
1408	    lv_anim_t a;
1409	
1410	    /* 转场中禁止再转；但盘面旋转本身可以被下一次 KEY1 打断（#2）。 */
1411	    if (UD.fill == NULL || (s_busy && s_tr_anim != NULL)) {
1412	        return;
1413	    }
1414	    a0 = (int)s_angle;
1415	
1416	    if (s_rot_anim != NULL) {
1417	        /* ANIMATION #2：从当前角重定目标，120ms；旧 B 升为 A。 */
1418	        lv_anim_delete(&s_rot_p, NULL);
1419	        s_rot_anim = NULL;
1420	        if (UD.fill != NULL) {
1421	            lv_obj_delete(UD.fill);
1422	            lv_obj_delete(UD.trk);
1423	        }
1424	        UD.fill = UD.fill2;
1425	        UD.trk = UD.trk2;
1426	        UD.fill2 = NULL;
1427	        UD.trk2 = NULL;
1428	        from_mode = s_rot_to_mode;
1429	        s_rot_oa0 = s_rot_oa_cur;
1430	        s_rot_ob0 = s_rot_ob_cur;
1431	        s_mode = from_mode;
1432	        duration = 120;
1433	    } else {
1434	        from_mode = s_mode;
1435	        s_rot_oa0 = 255;
1436	        s_rot_ob0 = 0;
1437	    }
1438	    s_rot_oa_cur = s_rot_oa0;
1439	    s_rot_ob_cur = s_rot_ob0;
1440	    to_mode = (from_mode + 1) % M_COUNT;
1441	
1442	    target = to_mode * 90;
1443	    while (target <= a0) {
1444	        target += 360;
1445	    }
1446	
1447	    s_rot_a0 = a0;
1448	    s_rot_a1 = target;
1449	    s_rot_from_mode = from_mode;
1450	    s_rot_to_mode = to_mode;
1451	    s_rot_swapped = false;
1452	    dial_sector(to_mode, (lv_opa_t)s_rot_ob0, &UD.fill2, &UD.trk2);
1453	    {
1454	        char buf[24];
1455	
1456	        snprintf(buf, sizeof(buf), "%02d → %02d", s_shown_mode + 1,
1457	                 to_mode + 1);
1458	        lv_label_set_text(UD.top_r, buf);
1459	    }
1460	
1461	    s_busy = true;
1462	    lv_anim_init(&a);
1463	    lv_anim_set_var(&a, &s_rot_p);
1464	    lv_anim_set_values(&a, 0, 1000);
1465	    lv_anim_set_duration(&a, duration);
1466	    lv_anim_set_path_cb(&a, lv_anim_path_ease_in_out);
1467	    lv_anim_set_exec_cb(&a, rot_exec);
1468	    lv_anim_set_ready_cb(&a, rot_ready);
1469	    s_rot_anim = lv_anim_start(&a);
1470	}
