4144	/* ── 电源键（键盘 ↑）────────────────────────────────────────────────
4145	 *
4146	 * 与 KEY1/KEY2 的 LP 状态机分开，任何屏都可用（真长按，按按住时长判定）：
4147	 *   短按（松手 < 800 ms）  熄屏 / 亮屏切换（SCR_IDLE，旧 helm_idle 语义）
4148	 *   长按（按住 ≥ 800 ms）  关机确认（SCR_SHUTDOWN phase 0，旧 helm_pwr 语义）
4149	 *   关机黑屏（phase 2）    按一下 = 开机回盘面
4150	 *
4151	 * 熄屏时按 ↑ 先唤醒：这次按下/抬起整对吃掉，避免抬起又被当成短按关回去。 */
4152	#define PWR_LONG_MS 800
4153	
4154	static struct {
4155	    bool down;
4156	    bool fired;
4157	    bool ignore_up;
4158	    uint32_t t0;
4159	} PWR;
4160	
4161	static bool s_keylog;   /* SIM_HELM_KEYLOG=1：每次按键/动作打一行（取证用） */
4162	
4163	static void keylog(const char *fmt, ...)
4164	{
4165	    va_list ap;
4166	
4167	    if (!s_keylog) {
4168	        return;
4169	    }
4170	    printf("helm-key: ");
4171	    va_start(ap, fmt);
4172	    vprintf(fmt, ap);
4173	    va_end(ap);
4174	    putchar('\n');
4175	    fflush(stdout);
4176	}
