4192	static void pwr_sleep(void)
4193	{
4194	    if (s_screen == SCR_IDLE || s_screen == SCR_SHUTDOWN) {
4195	        return;
4196	    }
4197	    s_idle_return = s_screen;
4198	    s_idle_s = 0;
4199	    s_screen = SCR_IDLE;
4200	    s_busy = false;
4201	    rebuild();
4202	}
