4207	        return;
4208	    }
4209	    s_power_mode = 0;
4210	    s_power_phase = 0;
4211	    s_power_ticks = 0;
4212	    s_screen = SCR_SHUTDOWN;
4213	    s_busy = false;
4214	    rebuild();
4215	}
