4217	static void pwr_event(bool down)
4218	{
4219	    if (down) {
4220	        if (PWR.down) {
4221	            return;             /* 自动重复已在上游去重，这里兜底 */
4222	        }
4223	        if (s_screen == SCR_IDLE ||
4224	            (s_screen == SCR_SHUTDOWN && s_power_phase == 2)) {
4225	            pwr_wake();
4226	            PWR.ignore_up = true;
4227	            keylog("POWER down -> wake (%s)", SCR_NAME[s_screen]);
4228	            return;
4229	        }

4230	        if (s_screen == SCR_SHUTDOWN) {
4231	            PWR.ignore_up = true;   /* 确认/进度页：电源键不参与 */
4232	            keylog("POWER down ignored (shutdown phase %d)", s_power_phase);
4233	            return;
4234	        }
4235	        if (LP.active) {
4236	            PWR.ignore_up = true;
4237	            keylog("POWER down ignored (LP active)");
4238	            return;
4239	        }
4240	        PWR.down = true;
4241	        PWR.fired = false;
4242	        PWR.t0 = lv_tick_get();
4243	        hint_set("长按关机 · 松手熄屏");
4244	        keylog("POWER down screen=%s", SCR_NAME[s_screen]);
4245	        return;
4246	    }
4247	
4248	    if (PWR.ignore_up) {
4249	        PWR.ignore_up = false;
4250	        keylog("POWER up consumed (wake)");
4251	        return;
4252	    }
4253	    if (!PWR.down) {
4254	        return;
4255	    }
4256	    PWR.down = false;
4257	    {
4258	        const uint32_t held = lv_tick_get() - PWR.t0;
4259	
4260	        hint_clear();
4261	        if (PWR.fired) {
4262	            PWR.fired = false;
4263	            keylog("POWER up held=%ums (shutdown already fired)", held);
4264	            return;
4265	        }
4266	        if (held >= PWR_LONG_MS) {
4267	            keylog("POWER up held=%ums -> shutdown", held);
4268	            pwr_shutdown_confirm();
4269	        } else {
4270	            keylog("POWER up held=%ums -> sleep", held);
4271	            pwr_sleep();
4272	        }
4273	    }
4274	}
4275	
4276	static void pwr_tick(void)
4277	{
4278	    if (!PWR.down || PWR.fired) {
4279	        return;
4280	    }
4281	    {
4282	        const uint32_t held = lv_tick_get() - PWR.t0;
4283	
4284	        if (held >= PWR_LONG_MS) {
4285	            PWR.fired = true;
4286	            hint_clear();
4287	            keylog("POWER long held=%ums -> shutdown", held);
4288	            pwr_shutdown_confirm();
4289	        }
4290	    }
4291	}
