4293	static void ui_tick(lv_timer_t *t)
4294	{
4295	    (void)t;
4296	    for (;;) {
4297	        int key = 0;
4298	        bool down = false;
4299	
4300	        if (!sim_display_take_key_event(&key, &down)) {
4301	            break;
4302	        }
4303	        s_idle_s = 0;
4304	        if (key == 3) {
4305	            pwr_event(down);    /* 电源键有自己的短按/长按，不参与 LP */
4306	            continue;
4307	        }
4308	        keylog("KEY%d %s screen=%s", key, down ? "down" : "up",
4309	               SCR_NAME[s_screen]);
4310	        if (s_screen == SCR_IDLE) {
4311	            if (down) {
4312	                keylog("KEY%d wake -> %s", key, SCR_NAME[s_idle_return]);
4313	                s_screen = s_idle_return;
4314	                s_busy = false;
4315	                rebuild();
4316	            }
4317	            continue;
4318	        }
4319	        if (s_busy) {
4320	            const bool dial_rot =
4321	                (s_screen == SCR_DIAL && s_tr_anim == NULL && s_rot_anim != NULL);
4322	
4323	            if (!(dial_rot && key == 1)) {
4324	                continue;
4325	            }
4326	        }
4327	        if (down) {
4328	            if (LP.active) {
4329	                continue;
4330	            }
4331	            if ((key == 1 && screen_has_lp1()) ||
4332	                (key == 2 && screen_has_lp2())) {
4333	                lp_begin(key);
4334	            } else {
4335	                do_short(key);
4336	            }
4337	        } else {
4338	            if (LP.active && LP.key == key) {
4339	                const uint32_t held = lv_tick_get() - LP.t0;
4340	
4341	                if (held < 160) {
4342	                    LP.active = false;
4343	                    lp_ui_clear();
4344	                    hint_clear();
4345	                    if (s_screen == SCR_DIAL) {
4346	                        dial_content(s_mode);
4347	                    }
4348	                    keylog("KEY%d up held=%ums -> short", key, held);
4349	                    do_short(key);
4350	                } else {
4351	                    keylog("KEY%d up held=%ums -> cancel", key, held);
4352	                    lp_cancel();
4353	                }
4354	            }
4355	        }
4356	    }
4357	    lp_tick();
4358	    pwr_tick();
4359	    if (s_toast_until != 0 && lv_tick_get() > s_toast_until) {
4360	        s_toast_until = 0;
4361	        if (!LP.active) {
4362	            hint_clear();
4363	        }
4364	    }
4365	    tour_tick();
