4823	static void data_tick(lv_timer_t *t)
4824	{
4825	    (void)t;
4826	    if (s_freeze) {
4827	        return;
4828	    }
4829	    s_clock_tick++;
4830	    if (s_clock_tick % 60 == 0) {
4831	        s_min = (s_min + 1) % (24 * 60);
4832	        if (s_screen == SCR_DIAL) {
4833	            dial_status_refresh();
4834	        }
4835	    }
4836	    if (s_clock_tick % 120 == 0 && s_batt > 5) {
4837	        s_batt--;
4838	        if (s_screen == SCR_DIAL) {
4839	            dial_status_refresh();
4840	        }
4841	    }
4842	    if (s_sens_search >= 0) {
4843	        sensor_tick();
4844	    }
4845	    if (s_sens_connect_dev >= 0) {
4846	        s_scan_ticks++;
4847	        if (s_scan_ticks >= 2) {
4848	            const int k = s_sens_kind;
4849	            const int d = s_sens_connect_dev;
4850	
4851	            s_sens_connect_dev = -1;
4852	            s_sens_on[k] = true;
4853	            s_sens_bars[k] = 4;
4854	            snprintf(s_sens_dev[k], sizeof(s_sens_dev[0]), "%s",
4855	                     SENS_NEARBY[k][d]);
4856	            toast("已连接");
4857	            if (s_screen == SCR_SENSOR_SCAN) {
4858	                rebuild();
4859	            }
4860	        }
4861	    }
4862	    if (s_phone_pair_s > 0) {
4863	        s_phone_pair_s--;
4864	        if (s_phone_pair_s == 0) {
4865	            s_phone_pair_s = -1;
4866	            toast("配对超时 · 请重试");
4867	            if (s_screen == SCR_BLUETOOTH) {
4868	                rebuild();
4869	            }
4870	        } else if (s_screen == SCR_BLUETOOTH) {
4871	            setl_refresh_values();
4872	        }
4873	    }
4874	
4875	    if (s_screen == SCR_SHUTDOWN) {
4876	        if (s_power_phase == 1) {
4877	            s_power_ticks++;
4878	            if (s_power_ticks >= 4) {
4879	                s_power_phase = 2;
4880	                s_power_ticks = 0;
4881	                rebuild();
4882	            } else {
4883	                rebuild();
4884	            }
4885	        } else if (s_power_phase == 2) {
4886	            s_power_ticks++;
4887	            if (s_power_mode == 1 && s_power_ticks >= 3) {
4888	                s_power_phase = 0;
4889	                s_power_ticks = 0;
4890	                s_screen = SCR_DIAL;
4891	                s_busy = false;
4892	                rebuild();
4893	            }
4894	        }
4895	        return;
4896	    }
4897	
4898	    if (R.active) {
4899	        const bool was_paused = R.paused;
4900	
4901	        ride_advance_1s();
4902	        if (s_screen == SCR_RIDE) {
4903	            if (R.paused != was_paused) {
4904	                rebuild();      /* 自动暂停/自动继续：顶部标签与颜色要换 */
4905	            } else {
4906	                ride_refresh();
4907	            }
4908	        } else if (s_screen == SCR_NAV) {
4909	            nav_refresh();
4910	#ifdef SIM_WITH_UI
4911	            if (s_nav_view != NULL) {
4912	                vmap_view_set_center(s_nav_view,
4913	                                     s_nav_lon + R.dist_km * 0.00004,
4914	                                     s_nav_lat);
4915	            }
4916	#endif
4917	        } else if (s_screen == SCR_DIAL) {
4918	            if (!LP.active && s_rot_anim == NULL) {
4919	                dial_content(s_mode);
4920	            }
4921	            dial_status_refresh();
4922	        }
4923	    }
4924	
4925	    /* 导航状态机：偏航 → 重规划 → 回到正常；到终点 → 到达横幅。 */
4926	    if (s_nav_active) {
4927	        s_nav_ticks++;
4928	        if (s_nav_phase == 0 && s_nav_ticks >= 45) {
4929	            s_nav_phase = 1;
4930	            s_nav_phase_s = 0;
4931	            toast("偏航 · 正在重新规划");
4932	            if (s_screen == SCR_NAV) {
4933	                rebuild();
4934	            }
4935	        } else if (s_nav_phase == 1) {
4936	            s_nav_phase_s++;
4937	            if (s_reroute && s_nav_phase_s >= 4) {
4938	                s_nav_phase = 0;
4939	                s_nav_turn = (s_nav_turn + 1) % 4;
