71	static inline uint32_t rgb565_to_xrgb(uint16_t c)
72	{
73	    uint32_t r = (uint32_t)((c >> 11) & 0x1Fu);
74	    uint32_t g = (uint32_t)((c >> 5) & 0x3Fu);
75	    uint32_t b = (uint32_t)(c & 0x1Fu);
76	
77	    r = (r << 3) | (r >> 2);
78	    g = (g << 2) | (g >> 4);
79	    b = (b << 3) | (b >> 2);
80	    return (r << 16) | (g << 8) | b;
81	}
