83	/* 把影子缓冲的一块画到窗口（只画脏矩形，缩放用最近邻）。 */
84	static void blit_rect(int x0, int y0, int w, int h)
85	{
86	    if (s.headless || !s.dpy || !s.img) {
87	        return;
88	    }
89	
90	    const int sc = s.scale;
91	    const int iw = s.w * sc;
92	    const bool fast = (s.img->bits_per_pixel == 32);
93	
94	    for (int y = 0; y < h; y++) {
95	        const uint16_t *src = s.shadow + (size_t)(y0 + y) * (size_t)s.w + x0;
96	        for (int sy = 0; sy < sc; sy++) {
97	            int row = (y0 + y) * sc + sy;
98	            for (int x = 0; x < w; x++) {
99	                uint32_t rgb = rgb565_to_xrgb(src[x]);
100	                for (int sx = 0; sx < sc; sx++) {
101	                    int col = (x0 + x) * sc + sx;
102	                    if (fast) {
103	                        ((uint32_t *)s.img->data)[(size_t)row * (size_t)iw + col] = rgb;
104	                    } else {
105	                        XPutPixel(s.img, col, row, rgb);
106	                    }
107	                }
108	            }
109	        }
110	    }
111	    XPutImage(s.dpy, s.win, s.gc, s.img, x0 * sc, y0 * sc, x0 * sc, y0 * sc,
112	              (unsigned)w * (unsigned)sc, (unsigned)h * (unsigned)sc);
113	    XFlush(s.dpy);
114	}
