118	static void flush_cb(lv_display_t *disp, const lv_area_t *area, uint8_t *px_map)
119	{
120	    const int w = (int)lv_area_get_width(area);
121	    const int h = (int)lv_area_get_height(area);
122	    const uint16_t *px = (const uint16_t *)px_map;
123	
124	    for (int y = 0; y < h; y++) {
125	        memcpy(s.shadow + (size_t)(area->y1 + y) * (size_t)s.w + area->x1,
126	               px + (size_t)y * (size_t)w, (size_t)w * 2u);
127	    }
128	    blit_rect(area->x1, area->y1, w, h);
129	    lv_display_flush_ready(disp);
130	}
