141	static void key_push(uint32_t key)
142	{
143	    int next = (s.key_tail + 1) % (int)(sizeof(s.keys) / sizeof(s.keys[0]));
144	
145	    if (next == s.key_head) {
146	        return;
147	    }
148	    s.keys[s.key_tail] = key;
149	    s.key_tail = next;
150	}
151	
152	static void keypad_read(lv_indev_t *indev, lv_indev_data_t *data)
153	{
154	    (void)indev;
155	    if (s.key_head != s.key_tail) {
156	        s.last_key = s.keys[s.key_head];
157	        s.key_head = (s.key_head + 1) % (int)(sizeof(s.keys) / sizeof(s.keys[0]));
158	        data->state = LV_INDEV_STATE_PRESSED;
159	    } else {
160	        data->state = LV_INDEV_STATE_RELEASED;
161	    }
162	    data->key = s.last_key;
163	}
