166	{
167	    int next = (s.raw_tail + 1) % (int)(sizeof(s.raw_keys) / sizeof(s.raw_keys[0]));
168	
169	    if (next == s.raw_head) {
170	        return;
171	    }
172	    s.raw_keys[s.raw_tail] = k;
173	    s.raw_tail = next;
