197	static void key_event_push(int key, bool down)
198	{
199	    int next = (s.k2_tail + 1) % (int)(sizeof(s.keys2) / sizeof(s.keys2[0]));
200	
201	    if (next == s.k2_head) {
202	        return;
203	    }
