209	bool sim_display_take_key_event(int *key, bool *down)
210	{
211	    if (s.k2_head == s.k2_tail) {
212	        return false;
213	    }
214	    if (key) {
215	        *key = s.keys2[s.k2_head].key;
216	    }
217	    if (down) {
218	        *down = s.keys2[s.k2_head].down != 0;
219	    }
220	    s.k2_head = (s.k2_head + 1) % (int)(sizeof(s.keys2) / sizeof(s.keys2[0]));
221	    return true;
222	}
