232	/* 物理按键 → 板端三键编号（1 = KEY1 / 2 = KEY2 / 3 = 电源）。
233	 * 方向键是给 `helm` 场景准备的主映射，数字 1/2/3 保留为等价别名，
234	 * 方便 headless 脚本和习惯数字键的人。返回 0 = 不是按键。 */
235	static int xkey_to_sim_key(KeySym ks)
236	{
237	    switch (ks) {
238	        case XK_Left:
239	        case XK_1:
240	            return 1;
241	        case XK_Right:
242	        case XK_2:
243	            return 2;
244	        case XK_Up:
245	        case XK_3:
246	            return 3;
247	        default:
248	            return 0;
249	    }
250	}
251	
252	static uint32_t xkey_to_lv(KeySym ks)
253	{
254	    switch (ks) {
255	        case XK_Left:  return LV_KEY_LEFT;
256	        case XK_Right: return LV_KEY_RIGHT;
257	        case XK_Up:    return LV_KEY_UP;
258	        case XK_Down:  return LV_KEY_DOWN;
259	        case XK_Return:
260	        case XK_KP_Enter: return LV_KEY_ENTER;
261	        case XK_Escape:   return LV_KEY_ESC;
262	        case XK_BackSpace:return LV_KEY_BACKSPACE;
263	        case XK_Tab:      return LV_KEY_NEXT;
264	        case XK_Home:     return LV_KEY_HOME;
265	        case XK_End:      return LV_KEY_END;
266	        default: return 0;
267	    }
268	}
