279	/* ── 事件循环 ──────────────────────────────────────────────────── */
280	
281	/* 窗口一显示出来就抓键盘焦点：不等用户先点一下。必须等窗口真正
282	 * viewable 再 XSetInputFocus，否则 X 会报 BadMatch（WM 重父化期间）。 */
283	static void focus_when_viewable(void)
284	{
285	    XWindowAttributes attr;
286	
287	    if (s.focus_done) {
288	        return;
289	    }
290	    if (XGetWindowAttributes(s.dpy, s.win, &attr) &&
291	        attr.map_state == IsViewable) {
292	        XSetInputFocus(s.dpy, s.win, RevertToParent, CurrentTime);
293	        XRaiseWindow(s.dpy, s.win);
294	        XFlush(s.dpy);
295	        s.focus_done = true;
296	    }
297	}
298	
299	bool sim_display_pump(void)
300	{
301	    if (s.headless || !s.dpy) {
302	        return !s.quit;
303	    }
304	
305	    focus_when_viewable();
306	    while (XPending(s.dpy)) {
307	        XEvent ev;
308	
309	        XNextEvent(s.dpy, &ev);
310	        switch (ev.type) {
311	            case Expose:
312	                if (ev.xexpose.count == 0) {
313	                    blit_rect(0, 0, s.w, s.h);
314	                }
315	                break;
316	            case MotionNotify:
317	                s.mx = ev.xmotion.x / s.scale;
318	                s.my = ev.xmotion.y / s.scale;
319	                if (s.mx < 0) s.mx = 0;
320	                if (s.my < 0) s.my = 0;
321	                if (s.mx > s.w - 1) s.mx = s.w - 1;
322	                if (s.my > s.h - 1) s.my = s.h - 1;
323	                break;
324	            case ButtonPress:
325	                if (ev.xbutton.button == Button1) {
326	                    s.pressed = true;
327	                } else if (ev.xbutton.button == Button4) {
328	                    s.wheel++;      /* 滚轮上 = 放大 */
329	                } else if (ev.xbutton.button == Button5) {
330	                    s.wheel--;      /* 滚轮下 = 缩小 */
331	                }
332	                break;
333	            case ButtonRelease:
334	                if (ev.xbutton.button == Button1) {
335	                    s.pressed = false;
336	                }
337	                break;
338	            case KeyPress: {
339	                KeySym ks = XLookupKeysym(&ev.xkey, 0);
340	                uint32_t key = xkey_to_lv(ks);
341	
342	                if (key) {
343	                    key_push(key);
344	                }
345	                /* 板端三键（按下沿）：← = KEY1，→ = KEY2，↑ = 电源；
346	                 * 数字 1/2/3 是等价别名。按住时的自动重复在这里去重。 */
347	                {
348	                    const int n = xkey_to_sim_key(ks);
349	
350	                    if (n != 0 && !s.key_down[n]) {
351	                        s.key_down[n] = true;
352	                        key_event_push(n, true);
353	                    }
354	                }
355	                /* `vmap` 场景的快捷键（其它场景不轮询，等于不存在）。 */
356	                switch (ks) {
357	                    case XK_1: raw_key_push('1'); break;
358	                    case XK_2: raw_key_push('2'); break;
359	                    case XK_3: raw_key_push('3'); break;
360	                    case XK_r: raw_key_push('r'); break;
361	                    case XK_f: raw_key_push('f'); break;
362	                    case XK_i: raw_key_push('i'); break;
363	                    case XK_c: raw_key_push('c'); break;
364	                    case XK_plus: case XK_equal: case XK_KP_Add:
365	                        raw_key_push('+');
366	                        break;
367	                    case XK_minus: case XK_KP_Subtract:
368	                        raw_key_push('-');
369	                        break;
370	                    default:
371	                        break;
372	                }
373	                break;
374	            }
375	            case KeyRelease: {
376	                KeySym ks = XLookupKeysym(&ev.xkey, 0);
377	                const int n = xkey_to_sim_key(ks);
378	
379	                if (n != 0 && s.key_down[n]) {
380	                    s.key_down[n] = false;
381	                    key_event_push(n, false);
382	                }
383	                break;
384	            }
385	            case ClientMessage:
386	                if ((Atom)ev.xclient.data.l[0] == s.wm_delete) {
387	                    s.quit = true;
388	                }
389	                break;
390	            case DestroyNotify:
391	                s.quit = true;
392	                break;
393	            default:
394	                break;
395	        }
396	    }
397	    return !s.quit;
398	}
