400	/* ── 初始化 ────────────────────────────────────────────────────── */
401	
402	static bool shadow_alloc(void)
403	{
404	    s.shadow = calloc((size_t)s.w * (size_t)s.h, sizeof(uint16_t));
405	    if (!s.shadow) {
406	        fprintf(stderr, "sim: out of memory for shadow framebuffer\n");
407	        return false;
408	    }
409	    for (size_t i = 0; i < (size_t)s.w * (size_t)s.h; i++) {
410	        s.shadow[i] = 0xFFFF;
411	    }
412	    return true;
413	}
414	
415	/* XStoreName 按 Latin-1 解释，中文/箭头会变乱码；现代 WM 认的是
416	 * _NET_WM_NAME(UTF8_STRING)，两边都写。 */
417	static void set_window_title(const char *title)
418	{
419	    const char *t = (title != NULL && title[0] != '\0') ? title : "lvgl_sim";
420	
421	    XStoreName(s.dpy, s.win, t);
422	    XChangeProperty(s.dpy, s.win, XInternAtom(s.dpy, "_NET_WM_NAME", False),
423	                    XInternAtom(s.dpy, "UTF8_STRING", False), 8,
424	                    PropModeReplace, (const unsigned char *)t, (int)strlen(t));
425	}
426	
427	static bool window_open(const sim_cfg_t *cfg)
428	{
429	    const int scr = DefaultScreen(s.dpy);
430	    const int win_w = s.w * s.scale;
431	    const int win_h = s.h * s.scale;
432	
433	    s.win = XCreateSimpleWindow(s.dpy, RootWindow(s.dpy, scr), 0, 0,
434	                                (unsigned)win_w, (unsigned)win_h, 0,
435	                                BlackPixel(s.dpy, scr), WhitePixel(s.dpy, scr));
436	    set_window_title(cfg->title);
437	
438	    XSizeHints hints;
439	    memset(&hints, 0, sizeof(hints));
440	    hints.flags = PMinSize | PMaxSize;
441	    hints.min_width = hints.max_width = win_w;
442	    hints.min_height = hints.max_height = win_h;
443	    XSetWMNormalHints(s.dpy, s.win, &hints);
444	
445	    s.wm_delete = XInternAtom(s.dpy, "WM_DELETE_WINDOW", False);
446	    XSetWMProtocols(s.dpy, s.win, &s.wm_delete, 1);
447	
448	    XSelectInput(s.dpy, s.win,
449	                 ExposureMask | ButtonPressMask | ButtonReleaseMask |
450	                 PointerMotionMask | KeyPressMask | KeyReleaseMask |
451	                 StructureNotifyMask);
452	
453	    s.gc = XCreateGC(s.dpy, s.win, 0, NULL);
454	
455	    s.img = XCreateImage(s.dpy, DefaultVisual(s.dpy, scr),
456	                         (unsigned)DefaultDepth(s.dpy, scr), ZPixmap, 0, NULL,
457	                         (unsigned)win_w, (unsigned)win_h, 32, 0);
458	    if (!s.img) {
459	        fprintf(stderr, "sim: XCreateImage failed\n");
460	        return false;
461	    }
462	    s.img->data = calloc((size_t)s.img->bytes_per_line, (size_t)win_h);
463	    if (!s.img->data) {
464	        fprintf(stderr, "sim: out of memory for XImage\n");
465	        return false;
466	    }
467	
468	    XMapWindow(s.dpy, s.win);
469	    XFlush(s.dpy);
470	
471	    if (s.img->bits_per_pixel != 32) {
472	        fprintf(stderr, "sim: warning: X server is %d bpp, using slow XPutPixel path\n",
473	                s.img->bits_per_pixel);
474	    }
475	    return true;
476	}
477	
478	bool sim_display_init(const sim_cfg_t *cfg)
479	{
480	    s.w = cfg->width > 0 ? cfg->width : 240;
481	    s.h = cfg->height > 0 ? cfg->height : 400;
482	    s.scale = cfg->scale > 0 ? cfg->scale : 2;
483	    s.headless = cfg->headless;
484	    s.quit = false;
485	
486	    if (!shadow_alloc()) {
487	        return false;
488	    }
489	    if (s.headless) {
490	        return true;
491	    }
492	
493	    s.dpy = XOpenDisplay(NULL);
494	    if (!s.dpy) {
495	        fprintf(stderr, "sim: cannot open X display; use --headless --shot out.png\n");
496	        return false;
497	    }
498	    /* 按住键不要生成 X 层的 KeyRelease 抖动：长按判定只认真正的抬起。 */
499	    {
500	        Bool supported = False;
501	
502	        XkbSetDetectableAutoRepeat(s.dpy, True, &supported);
503	    }
504	    return window_open(cfg);
505	}
