507	void sim_lvgl_bind(void)
508	{
509	    /* 两个 1/10 屏的局部缓冲：和设备的渲染模式一致，刷新时只送脏矩形 */
510	    const uint32_t stride = (uint32_t)s.w;
511	    const uint32_t lines = 40;
512	    const uint32_t bytes = stride * lines * 2u;
513	    void *buf1 = lv_malloc(bytes);
514	    void *buf2 = lv_malloc(bytes);
515	
516	    lv_display_t *disp = lv_display_create(s.w, s.h);
517	
518	    lv_display_set_flush_cb(disp, flush_cb);
519	    lv_display_set_buffers(disp, buf1, buf2, bytes, LV_DISPLAY_RENDER_MODE_PARTIAL);
520	    lv_display_set_default(disp);
521	
522	    s.indev_ptr = lv_indev_create();
523	    lv_indev_set_type(s.indev_ptr, LV_INDEV_TYPE_POINTER);
524	    lv_indev_set_read_cb(s.indev_ptr, pointer_read);
525	
526	    s.indev_key = lv_indev_create();
527	    lv_indev_set_type(s.indev_key, LV_INDEV_TYPE_KEYPAD);
528	    lv_indev_set_read_cb(s.indev_key, keypad_read);
529	    lv_indev_set_group(s.indev_key, sim_input_group());
530	}
