539	void sim_display_shutdown(void)
540	{
541	    if (s.img) {
542	        /* XDestroyImage 会 free(data) */
543	        XDestroyImage(s.img);
544	        s.img = NULL;
545	    }
546	    if (s.gc && s.dpy) {
547	        XFreeGC(s.dpy, s.gc);
548	        s.gc = NULL;
549	    }
550	    if (s.win && s.dpy) {
551	        XDestroyWindow(s.dpy, s.win);
552	        s.win = 0;
553	    }
554	    if (s.dpy) {
555	        XCloseDisplay(s.dpy);
556	        s.dpy = NULL;
557	    }
558	    free(s.shadow);
559	    s.shadow = NULL;
560	}
